using System.Collections.Frozen;
using System.IO.Compression;
using System.Text;
using DfoServer.GameWorld.Dungeons;

namespace DfoServer.Game.Dungeons;

// 由历史Script.patched6到纯净旧模型的逐MAP前后差异生成，再与新模型逐行复核。
// 仅28020个来源明确的旧注入行；93个来源未证行不在清单内，不能仅凭5409或相似坐标认作支援兵。
// DCM1负载保存规范MAP路径、原APC ordinal、x、y；已逐行证明的固定字段为5409/x/y/0/0/0、[character]/[normal]。
// 压缩常量只在首次分类时有界解码一次，不读运行目录、不扫描PVF，不以整份PVF哈希作为门禁。
internal static class DungeonCompanionLegacyRows
{
    private const int RowCount = 28020;
    private const int MaximumPathBytes = 512;
    private readonly record struct Row(int Ordinal, int X, int Y);
    private static readonly FrozenDictionary<string, Row> Rows = Load();

    public static bool IsKnown(string mapPath, int ordinal, DungeonRoomAiCharacter source)
    {
        string path = mapPath.Contains('\\') ? mapPath.Replace('\\', '/') : mapPath;
        return source.Id == 5409 && source.Faction == "[character]" && source.RankKind == "[normal]" &&
            Rows.TryGetValue(path, out var known) && known.Ordinal == ordinal &&
            source.RawValues is [5409, var x, var y, 0, 0, 0] && x == known.X && y == known.Y;
    }

    private static FrozenDictionary<string, Row> Load()
    {
        if (Data.Length > 1048576) throw new InvalidDataException("伴侣旧行清单压缩数据超界");
        using var compressed = new MemoryStream(Convert.FromBase64String(Data), writable: false);
        using var decoded = new GZipStream(compressed, CompressionMode.Decompress);
        var utf8 = new UTF8Encoding(false, true);
        using var reader = new BinaryReader(decoded, utf8);
        if (reader.ReadUInt32() != 0x314D4344 || reader.ReadInt32() != RowCount)
            throw new InvalidDataException("伴侣旧行清单格式或数量无效");
        var rows = new Dictionary<string, Row>(RowCount, StringComparer.OrdinalIgnoreCase);
        // 数量固定、每行路径最多512B；逐字段读取，不执行无界解压或接收外部数据。
        for (int index = 0; index < RowCount; index++)
        {
            int length = reader.ReadUInt16();
            if (length is < 1 or > MaximumPathBytes) throw new InvalidDataException("伴侣旧行清单路径超界");
            byte[] bytes = reader.ReadBytes(length);
            if (bytes.Length != length) throw new InvalidDataException("伴侣旧行清单被截断");
            string path = utf8.GetString(bytes);
            int ordinal = reader.ReadInt32(), x = reader.ReadInt32(), y = reader.ReadInt32();
            if (!path.StartsWith("map/", StringComparison.Ordinal) || !path.EndsWith(".map", StringComparison.Ordinal) ||
                path != path.ToLowerInvariant() || path.Contains('\\') || path.Contains("//", StringComparison.Ordinal) ||
                path.Contains("/./", StringComparison.Ordinal) || path.Contains("/../", StringComparison.Ordinal) ||
                ordinal is < 0 or >= 64 || !rows.TryAdd(path, new(ordinal, x, y)))
                throw new InvalidDataException("伴侣旧行清单路径、行号或重复身份无效");
        }
        if (decoded.ReadByte() != -1) throw new InvalidDataException("伴侣旧行清单含多余数据");
        return rows.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
    }

